  p_ModelConfiguration_ff9802e995a7 := '{
  "LLM": {
    "SupportsNativeToolCalling": true,
    "DefaultToNativeToolCalling": false,
    "NativeControlFlow": "implicit",
    "NativeToolResults": true
  }
}';
