-- Save MJ: Queries (core SP call only)
DO $mj$
DECLARE
  p_ID_6641f9bbe265 UUID;
  p_Name_6641f9bbe265 VARCHAR(255);
  p_CategoryID_6641f9bbe265 UUID;
  p_UserQuestion_6641f9bbe265 TEXT;
  p_Description_6641f9bbe265 TEXT;
  p_SQL_6641f9bbe265 TEXT;
  p_TechnicalDescription_6641f9bbe265 TEXT;
  p_OriginalSQL_6641f9bbe265 TEXT;
  p_Feedback_6641f9bbe265 TEXT;
  p_Status_6641f9bbe265 VARCHAR(15);
  p_QualityRank_6641f9bbe265 INTEGER;
  p_ExecutionCostRank_6641f9bbe265 INTEGER;
  p_UsesTemplate_6641f9bbe265 BOOLEAN;
  p_AuditQueryRuns_6641f9bbe265 BOOLEAN;
  p_CacheEnabled_6641f9bbe265 BOOLEAN;
  p_CacheTTLMinutes_6641f9bbe265 INTEGER;
  p_CacheMaxSize_6641f9bbe265 INTEGER;
  p_EmbeddingVector_6641f9bbe265 TEXT;
  p_EmbeddingModelID_6641f9bbe265 UUID;
  p_CacheValidationSQL_6641f9bbe265 TEXT;
  p_SQLDialectID_6641f9bbe265 UUID;
  p_Reusable_6641f9bbe265 BOOLEAN;
  p_ExternalDataSourceID_6641f9bbe265 UUID;
  p_IsMaterialized_6641f9bbe265 BOOLEAN;
  p_Configuration_6641f9bbe265 TEXT;
BEGIN
  p_ID_6641f9bbe265 := 'EBF9166E-DEA4-4CEE-8D1F-56A903D0D1E6';
  p_Name_6641f9bbe265 := 'AIUsageByScope';
  p_CategoryID_6641f9bbe265 := '6C8C5BA5-D9D1-47A1-8EF8-E59DA57F9D22';
  p_UserQuestion_6641f9bbe265 := 'What is our AI usage, tokens, and spend broken down by primary scope entity and record?';
  p_Description_6641f9bbe265 := 'Aggregates AI usage facts by PrimaryScopeEntityID and PrimaryScopeRecordID. Supports optional filtering by scope entity, scope record, and date range.';
  p_SQL_6641f9bbe265 := '-- AI usage per tenant scope (PrimaryScopeEntityID + PrimaryScopeRecordID, + currency). Live-only.
--
-- Runs and every measure count model calls only; parallel parents are counted separately in
-- ParallelParents, because a parent''s ExecutionTimeMS spans its whole fan-out and it carries no
-- own cost. Cost is grouped by CostCurrency, with PricedRuns / UnpricedRuns beside it.
-- The window filters the base RunAt column (range-seekable on IX_AIPromptRun_RunAt).
-- Percentiles are PERCENTILE_CONT window functions (SQL Server 2019), parents nulled out,
-- collapsed with MAX.
SELECT
    x.PrimaryScopeEntityID,
    x.PrimaryScopeRecordID,
    x.CostCurrency,
    SUM(CASE WHEN x.IsParallelParent = 0 THEN 1 ELSE 0 END) AS Runs,
    SUM(CASE WHEN x.IsParallelParent = 0 AND x.Success = 1 THEN 1 ELSE 0 END) AS SucceededRuns,
    SUM(CASE WHEN x.IsParallelParent = 0 AND x.Success = 0 THEN 1 ELSE 0 END) AS FailedRuns,
    SUM(CASE WHEN x.IsParallelParent = 0 AND x.IsPriced = 1 THEN 1 ELSE 0 END) AS PricedRuns,
    SUM(CASE WHEN x.IsParallelParent = 0 AND x.IsPriced = 0 THEN 1 ELSE 0 END) AS UnpricedRuns,
    SUM(CASE WHEN x.IsParallelParent = 0 AND x.IsUnmeasured = 1 THEN 1 ELSE 0 END) AS UnmeasuredRuns,
    SUM(CASE WHEN x.IsParallelParent = 1 THEN 1 ELSE 0 END) AS ParallelParents,
    SUM(CASE WHEN x.IsParallelParent = 0 THEN x.TokensPrompt ELSE 0 END) AS TokensPrompt,
    SUM(CASE WHEN x.IsParallelParent = 0 THEN x.TokensCompletion ELSE 0 END) AS TokensCompletion,
    SUM(CASE WHEN x.IsParallelParent = 0 THEN x.TokensCacheRead ELSE 0 END) AS TokensCacheRead,
    SUM(CASE WHEN x.IsParallelParent = 0 THEN x.TokensCacheWrite ELSE 0 END) AS TokensCacheWrite,
    SUM(CASE WHEN x.IsParallelParent = 0 AND x.IsPriced = 1 THEN x.OwnCost ELSE 0 END) AS OwnCost,
    MAX(x.LatencyP50) AS LatencyP50,
    MAX(x.LatencyP95) AS LatencyP95,
    AVG(CASE WHEN x.IsParallelParent = 0 THEN x.FirstTokenTime END) AS AvgFirstTokenMS
FROM (
    SELECT
        f.PrimaryScopeEntityID,
        f.PrimaryScopeRecordID,
        f.CostCurrency,
        f.IsParallelParent,
        f.Success,
        f.IsPriced,
        f.IsUnmeasured,
        f.TokensPrompt,
        f.TokensCompletion,
        f.TokensCacheRead,
        f.TokensCacheWrite,
        f.OwnCost,
        f.FirstTokenTime,
        CASE WHEN f.IsParallelParent = 0 THEN
            PERCENTILE_CONT(0.5) WITHIN GROUP (ORDER BY f.ExecutionTimeMS)
                OVER (PARTITION BY f.PrimaryScopeEntityID, f.PrimaryScopeRecordID, f.CostCurrency, f.IsParallelParent)
        END AS LatencyP50,
        CASE WHEN f.IsParallelParent = 0 THEN
            PERCENTILE_CONT(0.95) WITHIN GROUP (ORDER BY f.ExecutionTimeMS)
                OVER (PARTITION BY f.PrimaryScopeEntityID, f.PrimaryScopeRecordID, f.CostCurrency, f.IsParallelParent)
        END AS LatencyP95
    FROM [__mj].vwAIUsageFacts f
    WHERE f.IsCompleted = 1
      {% if scopeEntityId %}
      AND f.PrimaryScopeEntityID = TRY_CONVERT(UUID, {{ scopeEntityId | sqlString }})
      {% endif %}
      {% if scopeRecordId %}
      AND f.PrimaryScopeRecordID = {{ scopeRecordId | sqlString }}
      {% endif %}
      {% if start %}
      AND f.RunAt >= {{ start | sqlDate }}
      {% endif %}
      {% if end %}
      AND f.RunAt < {{ end | sqlDate }}
      {% endif %}
) x
GROUP BY
    x.PrimaryScopeEntityID,
    x.PrimaryScopeRecordID,
    x.CostCurrency
';
  p_TechnicalDescription_6641f9bbe265 := 'Aggregates vwAIUsageFacts by PrimaryScopeEntityID, PrimaryScopeRecordID and CostCurrency. Runs and every measure count model calls only; parallel parents are counted separately in ParallelParents. Parameters scopeEntityId, scopeRecordId, start and end are optional (template conditionals); the window filters the base RunAt column. Latency percentiles are PERCENTILE_CONT window functions over non-parent runs, collapsed with MAX (SQL Server 2019+).';
  p_Status_6641f9bbe265 := 'Approved';
  p_QualityRank_6641f9bbe265 := 9;
  p_ExecutionCostRank_6641f9bbe265 := 3;
  p_UsesTemplate_6641f9bbe265 := TRUE;
  p_AuditQueryRuns_6641f9bbe265 := FALSE;
  p_CacheEnabled_6641f9bbe265 := FALSE;
