BEGIN
  p_ID_84f14e694501 := '7C9243A8-0B86-4CFA-A3DF-9A0E50FBC605';
  p_Name_84f14e694501 := 'AIUsageByUser';
  p_CategoryID_84f14e694501 := '6C8C5BA5-D9D1-47A1-8EF8-E59DA57F9D22';
  p_UserQuestion_84f14e694501 := 'What is our AI usage, spend, and token volume per user for chargeback attribution?';
  p_Description_84f14e694501 := 'Aggregates AI usage facts by UserID to support user-level chargeback, attribution, and consumption monitoring.';
  p_SQL_84f14e694501 := '-- AI usage per user (+ currency). Live-only.
--
-- Rows are model calls: parallel parents are excluded (their arms carry the work and the cost).
-- Cost is grouped by CostCurrency so two currencies are never summed into one unitless number, and
-- PricedRuns / UnpricedRuns travel beside it — an unpriced run is excluded from OwnCost, not zero.
-- The window filters the base RunAt column (range-seekable on IX_AIPromptRun_RunAt).
SELECT
    UserID,
    CostCurrency,
    COUNT(*) AS Runs,
    SUM(CASE WHEN IsPriced = 1 THEN 1 ELSE 0 END) AS PricedRuns,
    SUM(CASE WHEN IsPriced = 0 THEN 1 ELSE 0 END) AS UnpricedRuns,
    SUM(CASE WHEN IsPriced = 1 THEN OwnCost ELSE 0 END) AS OwnCost,
    SUM(TokensPrompt) AS TokensPrompt,
    SUM(TokensCompletion) AS TokensCompletion,
    MAX(RunAtUTC) AS LastRunAt
FROM [__mj].vwAIUsageFacts
WHERE IsCompleted = 1
  AND IsParallelParent = 0
  {% if start %}
  AND RunAt >= {{ start | sqlDate }}
  {% endif %}
  {% if end %}
  AND RunAt < {{ end | sqlDate }}
  {% endif %}
GROUP BY
    UserID,
    CostCurrency
';
  p_TechnicalDescription_84f14e694501 := 'Aggregates vwAIUsageFacts by UserID and CostCurrency over model calls only (parallel parents excluded), with optional start/end on the base RunAt column. Computes runs, priced/unpriced run counts, own cost over priced runs, prompt and completion tokens, and the most recent run timestamp.';
